#
# Simple correlations (latent constructs for B, mu, r)
#
#################

################# 10kb ################# 
pearson_10kb <- fread("sem/pearson_gw_10kb.csv")
setnames(pearson_10kb, old=c("avg_pi", "prop_del_sites", "B", "avg_rec", "avg_mut"),
                       new=c("pi", "E", "B", "r", "mu"))
pearson_10kb$V1 <- c("pi", "E", "B", "r", "mu")
var_names <- setdiff(names(pearson_10kb), "V1")

long <- pearson_10kb %>%
  pivot_longer(
    cols = -V1,
    names_to = "variable2",
    values_to = "value"
  ) %>%
  dplyr::rename(variable1 = V1) %>%
  filter(variable1 != variable2) %>%
  mutate(
    i = match(variable1, var_names),  
    j = match(variable2, var_names), 
    pair_key = paste(pmin(variable1, variable2), pmax(variable1, variable2), sep = "|")
  )

# lower triangle: correlations
corr_long <- long %>%
  filter(i > j, !is.na(value)) %>%
  transmute(
    pair_key,
    var1 = pmin(variable1, variable2),
    var2 = pmax(variable1, variable2),
    correlation = as.numeric(value)
  )

# upper triangle: p-values
pval_long <- long %>%
  filter(i < j, !is.na(value)) %>%
  transmute(
    pair_key,
    pvalue = as.numeric(value)
  )

pearson_10kb <- corr_long %>%
  left_join(pval_long, by = "pair_key") %>%
  arrange(., var1, var2)

pearson_10kb$scale <- 1e4

