p <- ggplot(data=pearson_cors, aes(x=pair_key, y=correlation, alpha=sig)) +
  geom_point(size=3) + geom_hline(yintercept=0, linetype="dashed", color="red") +
  facet_wrap(~scale/1e3, ncol=1) + theme_classic() + 
  scale_y_continuous(breaks=pretty_breaks()) +
  scale_alpha_manual(values = c("TRUE" = 1, "FALSE" = 0.35), 
                     labels=c("TRUE"="Significant", "FALSE"="Non-Significant"), name=NULL) +
  labs(title=NULL, x="Variable Pair", y="Pearson correlation") +
  theme(strip.text.y=element_text(size=16),     
        strip.text.x=element_text(size=16),    
        axis.title=element_text(size=16), 
        axis.text=element_text(size=12), 
        axis.text.x=element_text(size=12, angle = 90, hjust = 1, vjust = 0.5),
        legend.position="none")
save_plot("sem/pearson_gw.pdf", p, base_height=8, base_width=6)

