chr_fit_10kb <- dplyr::select(chr_fitmeasures_10kb, c("pvalue", "aic", "bic", "cfi", "gfi", "chrom", "DAG", "scale"))
chr_fit_100kb <- dplyr::select(chr_fitmeasures_100kb, c("pvalue", "aic", "bic", "cfi", "gfi", "chrom", "DAG", "scale"))
chr_fit_1Mb <- dplyr::select(chr_fitmeasures_1Mb, c("pvalue", "aic", "bic", "cfi", "gfi", "chrom", "DAG", "scale"))

chr_fitmeasures <- rbind.data.frame(chr_fit_10kb, chr_fit_100kb, chr_fit_1Mb) 

chr_fitmeasures <- chr_fitmeasures %>% 
  mutate(scale_offset = case_when(DAG == 3 ~ scale * 0.9, 
                                  DAG == 4 ~ scale * 1.1,
                                  TRUE ~ scale))

fwrite(dplyr::select(chr_fitmeasures, c(pvalue, cfi, chrom, DAG, scale)),
       "sem/fwd_simpi_chr_fitmeasures.csv")

