names(chr_LRT)[1] <- "pvalue"

fwrite(chr_LRT, "sem/chr_LRT_DAGs3-4.csv")

pc <- ggplot(data=chr_LRT, aes(x=chrom, y=-log10(pvalue))) +
  geom_point(size=3) + theme_classic() + 
  geom_hline(yintercept=-log10(0.05/num_chrom), linetype="dashed", color="darkgrey") +
  facet_wrap(~scale/1e3, scale="free_y", labeller=labeller(cutoff=model_labels)) + 
  scale_y_continuous(breaks=pretty_breaks()) +
  scale_x_continuous(breaks=1:num_chrom) +
  labs(title="LRT DAG 3 vs DAG 4", x="Chromosome", y=expression(-log[10](italic(p)))) +
  theme(strip.text=element_text(size=16),      
        axis.title=element_text(size=16), 
        axis.text.x=element_blank())
save_plot("sem/chr_LRT_DAGs3vs4.pdf", pc, base_height=6, base_width=12)

