#################

# per chromosome SEM models DAGs 3-4
## 10 kb
chr_params_10kb <- data.frame()
for(dag in 3:4) {
    chr_list <- list(length=num_chrom)
    for(c in 0:(num_chrom-1)) {
      tmp <- fread(paste("sem/lavaan_out/fwd_simpi_DAG", dag, 
                         "_params_10kb_chr", c, ".csv", sep=""))
      
      tmp$chrom <- c
      tmp$DAG <- dag

      chr_list[[c+1]] <- tmp
    }
    
    df <- do.call(rbind.data.frame, chr_list)
    chr_params_10kb <- rbind.data.frame(chr_params_10kb, df)
}
chr_params_10kb$scale <- 1e+4

## 100 kb
chr_params_100kb <- data.frame()
for(dag in 3:4) {
    chr_list <- list(length=num_chrom)
    for(c in 0:(num_chrom-1)) {
      tmp <- fread(paste("sem/lavaan_out/fwd_simpi_DAG", dag, 
                         "_params_100kb_chr", c, ".csv", sep=""))
      
      tmp$chrom <- c
      tmp$DAG <- dag

      chr_list[[c+1]] <- tmp
    }
    
    df <- do.call(rbind.data.frame, chr_list)
    chr_params_100kb <- rbind.data.frame(chr_params_100kb, df)
}
chr_params_100kb$scale <- 1e+5

## 1 Mb
chr_params_1Mb <- data.frame()
for(dag in 3:4) {
  chr_list <- list(length=num_chrom)
  for(c in 0:(num_chrom-1)) {
    tmp <- fread(paste("sem/lavaan_out/fwd_simpi_DAG", dag, 
                       "_params_1Mb_chr", c, ".csv", sep=""))
    
    tmp$chrom <- c
    tmp$DAG <- dag
    
    chr_list[[c+1]] <- tmp
  }
  
  df <- do.call(rbind.data.frame, chr_list)
  chr_params_1Mb <- rbind.data.frame(chr_params_1Mb, df)
}
chr_params_1Mb$scale <- 1e+6

chr_params <- rbind.data.frame(chr_params_10kb, chr_params_100kb, chr_params_1Mb)  %>%
  filter(., op=="~" | op==":=" | (lhs=="avg_mut" & op=="~~" & rhs=="prop_del_sites"))

# summaries
pcs <- filter(chr_params, DAG==4, lhs=="avg_pi", rhs=="avg_mut" | rhs=="B", pvalue < 0.05/num_chrom) %>% setDT()
pcs_wd <- dcast(pcs, chrom + DAG + scale ~ rhs, value.var = "est") %>% setDT()
pcs_wd[, ratio:=B/avg_mut]
pcs_wd[, `:=`(min_ratio=min(ratio, na.rm=T), max_ratio=max(ratio, na.rm=T), mean_ratio=mean(ratio, na.rm=T)), by=.(scale)]
pcs_wd_unique <- pcs_wd[, .SD[1], by = .(scale)]
pcs_wd_unique
# end summaries

chr_params$sig <- chr_params$pvalue < 0.05 / num_chrom # Bonferroni over autosomes
chr_params_ext <- left_join(chr_params, chr_fitmeasures,
                            by=c("chrom", "DAG", "scale"))

names(chr_params_ext)[8] <- "pvalue_est"
names(chr_params_ext)[15] <- "pvalue_DAG"

